namespace RecipeCommunity.Models;

public class Recipe
{
    public int Id { get; set; }
    public string Title { get; set; } = string.Empty;
    public string Category { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public List<string> Ingredients { get; set; } = [];
    public List<string> Steps { get; set; } = [];
    public string ImageEmoji { get; set; } = "🍽️";
    public int TotalRatings { get; set; }
    public int RatingSum { get; set; }

    public double AverageRating => TotalRatings > 0 ? (double)RatingSum / TotalRatings : 0;
}

public class RecipeSubmission
{
    public string Title { get; set; } = string.Empty;
    public string Category { get; set; } = string.Empty;
    public string Ingredients { get; set; } = string.Empty;
    public string Steps { get; set; } = string.Empty;
}

public class CategoryInfo
{
    public string Name { get; set; } = string.Empty;
    public string Emoji { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public int RecipeCount { get; set; }
}

using RecipeCommunity.Models;

namespace RecipeCommunity.Services;

public class RecipeService
{
    private readonly List<Recipe> _recipes;

    public RecipeService()
    {
        _recipes = CreateSeedData();
    }

    public List<CategoryInfo> GetCategories()
    {
        return _recipes
            .GroupBy(r => r.Category)
            .Select(g => new CategoryInfo
            {
                Name = g.Key,
                Emoji = g.First().ImageEmoji,
                Description = GetCategoryDescription(g.Key),
                RecipeCount = g.Count()
            })
            .OrderBy(c => c.Name)
            .ToList();
    }

    public List<Recipe> GetRecipesByCategory(string category)
    {
        return _recipes
            .Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase))
            .ToList();
    }

    public Recipe? GetRecipeById(int id)
    {
        return _recipes.FirstOrDefault(r => r.Id == id);
    }

    public void AddRating(int recipeId, int stars)
    {
        var recipe = _recipes.FirstOrDefault(r => r.Id == recipeId);
        if (recipe is not null && stars is >= 1 and <= 5)
        {
            recipe.TotalRatings++;
            recipe.RatingSum += stars;
        }
    }

    public void SubmitRecipe(RecipeSubmission submission)
    {
        var newId = _recipes.Max(r => r.Id) + 1;
        var recipe = new Recipe
        {
            Id = newId,
            Title = submission.Title,
            Category = submission.Category,
            Ingredients = submission.Ingredients
                .Split('\n', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries)
                .ToList(),
            Steps = submission.Steps
                .Split('\n', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries)
                .ToList(),
            ImageEmoji = GetCategoryEmoji(submission.Category)
        };
        _recipes.Add(recipe);
    }

    private static string GetCategoryDescription(string category) => category switch
    {
        "Breakfast" => "Start your day right with these morning favorites.",
        "Main Courses" => "Hearty dishes for lunch and dinner.",
        "Desserts" => "Sweet treats to satisfy your cravings.",
        "Soups & Salads" => "Light and refreshing options for any meal.",
        _ => "Explore delicious recipes in this category."
    };

    private static string GetCategoryEmoji(string category) => category switch
    {
        "Breakfast" => "🥞",
        "Main Courses" => "🍝",
        "Desserts" => "🍰",
        "Soups & Salads" => "🥗",
        _ => "🍽️"
    };

    private static List<Recipe> CreateSeedData() =>
    [
        new()
        {
            Id = 1, Title = "Classic Pancakes", Category = "Breakfast", ImageEmoji = "🥞",
            Description = "Fluffy golden pancakes perfect for a lazy weekend morning.",
            Ingredients = ["2 cups all-purpose flour", "2 tbsp sugar", "2 tsp baking powder", "1 tsp salt", "2 eggs", "1½ cups milk", "¼ cup melted butter", "1 tsp vanilla extract"],
            Steps = ["Whisk flour, sugar, baking powder, and salt in a large bowl.", "Beat eggs, milk, melted butter, and vanilla in a separate bowl.", "Pour wet ingredients into dry and stir until just combined (lumps are fine).", "Heat a non-stick pan over medium heat and lightly grease.", "Pour ¼ cup batter per pancake, cook until bubbles form, then flip.", "Serve with maple syrup, fresh berries, or whipped cream."],
            TotalRatings = 12, RatingSum = 52
        },
        new()
        {
            Id = 2, Title = "Avocado Toast", Category = "Breakfast", ImageEmoji = "🥑",
            Description = "Simple, nutritious, and endlessly customizable.",
            Ingredients = ["2 slices sourdough bread", "1 ripe avocado", "1 tbsp lemon juice", "Salt and pepper to taste", "Red pepper flakes", "2 eggs (optional)"],
            Steps = ["Toast bread until golden and crispy.", "Halve the avocado, remove pit, and scoop flesh into a bowl.", "Mash with lemon juice, salt, and pepper.", "Spread avocado mixture on toast.", "Top with red pepper flakes and a fried egg if desired."],
            TotalRatings = 8, RatingSum = 35
        },
        new()
        {
            Id = 3, Title = "Spaghetti Bolognese", Category = "Main Courses", ImageEmoji = "🍝",
            Description = "A rich and savory Italian classic the whole family will love.",
            Ingredients = ["1 lb spaghetti", "1 lb ground beef", "1 onion, diced", "3 cloves garlic, minced", "1 can (28 oz) crushed tomatoes", "2 tbsp tomato paste", "1 tsp dried oregano", "1 tsp dried basil", "Salt and pepper", "Parmesan cheese"],
            Steps = ["Cook spaghetti according to package directions; drain.", "Brown ground beef in a large skillet; drain excess fat.", "Add onion and garlic; cook until softened.", "Stir in crushed tomatoes, tomato paste, oregano, and basil.", "Simmer for 20 minutes, stirring occasionally.", "Season with salt and pepper.", "Serve sauce over spaghetti and top with Parmesan."],
            TotalRatings = 15, RatingSum = 68
        },
        new()
        {
            Id = 4, Title = "Grilled Chicken Tacos", Category = "Main Courses", ImageEmoji = "🌮",
            Description = "Zesty grilled chicken wrapped in warm tortillas.",
            Ingredients = ["1 lb chicken breast", "2 tbsp olive oil", "1 tbsp chili powder", "1 tsp cumin", "8 small tortillas", "1 cup shredded lettuce", "½ cup diced tomatoes", "½ cup shredded cheese", "Salsa and sour cream"],
            Steps = ["Mix olive oil, chili powder, and cumin; coat chicken.", "Grill chicken 6–7 minutes per side until cooked through.", "Let rest 5 minutes, then slice into strips.", "Warm tortillas on the grill or in a pan.", "Assemble tacos with chicken, lettuce, tomatoes, and cheese.", "Top with salsa and sour cream."],
            TotalRatings = 10, RatingSum = 45
        },
        new()
        {
            Id = 5, Title = "Chocolate Lava Cake", Category = "Desserts", ImageEmoji = "🍫",
            Description = "Decadent individual cakes with a molten chocolate center.",
            Ingredients = ["4 oz dark chocolate", "½ cup butter", "1 cup powdered sugar", "2 eggs", "2 egg yolks", "6 tbsp flour", "Butter and cocoa for ramekins"],
            Steps = ["Preheat oven to 425°F. Grease four ramekins with butter and dust with cocoa.", "Melt chocolate and butter together; stir in powdered sugar.", "Whisk in eggs and egg yolks, then fold in flour.", "Divide batter among ramekins.", "Bake 12–14 minutes until edges are firm but center is soft.", "Let cool 1 minute, invert onto plates, and serve immediately."],
            TotalRatings = 20, RatingSum = 95
        },
        new()
        {
            Id = 6, Title = "Strawberry Cheesecake", Category = "Desserts", ImageEmoji = "🍰",
            Description = "Creamy New York-style cheesecake with a fresh strawberry topping.",
            Ingredients = ["2 cups graham cracker crumbs", "⅓ cup sugar", "⅓ cup melted butter", "4 packages cream cheese", "1 cup sugar", "1 tsp vanilla", "4 eggs", "1 cup sour cream", "2 cups fresh strawberries", "¼ cup strawberry jam"],
            Steps = ["Mix crumbs, sugar, and butter; press into springform pan.", "Beat cream cheese, sugar, and vanilla until smooth.", "Add eggs one at a time, then mix in sour cream.", "Pour over crust and bake at 325°F for 55 minutes.", "Cool slowly in oven with door cracked.", "Top with sliced strawberries glazed with warmed jam."],
            TotalRatings = 14, RatingSum = 62
        },
        new()
        {
            Id = 7, Title = "Tomato Basil Soup", Category = "Soups & Salads", ImageEmoji = "🍅",
            Description = "A comforting bowl of velvety tomato soup with fresh basil.",
            Ingredients = ["2 cans (28 oz) whole tomatoes", "1 onion, diced", "3 cloves garlic", "2 cups vegetable broth", "½ cup heavy cream", "¼ cup fresh basil", "2 tbsp olive oil", "Salt and pepper"],
            Steps = ["Sauté onion and garlic in olive oil until soft.", "Add tomatoes and broth; bring to a boil.", "Simmer 20 minutes.", "Blend until smooth with an immersion blender.", "Stir in cream and chopped basil.", "Season with salt and pepper; serve with crusty bread."],
            TotalRatings = 9, RatingSum = 40
        },
        new()
        {
            Id = 8, Title = "Caesar Salad", Category = "Soups & Salads", ImageEmoji = "🥗",
            Description = "Crisp romaine tossed in a tangy homemade Caesar dressing.",
            Ingredients = ["1 large head romaine lettuce", "½ cup Parmesan cheese", "1 cup croutons", "2 cloves garlic", "2 anchovy fillets", "1 egg yolk", "2 tbsp lemon juice", "1 tsp Dijon mustard", "⅓ cup olive oil"],
            Steps = ["Wash and chop romaine into bite-sized pieces.", "Mince garlic and anchovies into a paste.", "Whisk paste with egg yolk, lemon juice, and mustard.", "Slowly drizzle in olive oil while whisking to emulsify.", "Toss lettuce with dressing, Parmesan, and croutons.", "Serve immediately with extra Parmesan on top."],
            TotalRatings = 7, RatingSum = 30
        }
    ];
}

