arguments.file_text:
@page "/"
@using RecipeCommunity.Services

<PageTitle>Recipe Community</PageTitle>

<div class="text-center mb-4">
    <h1 class="display-4">🍳 Recipe Community</h1>
    <p class="lead text-muted">Discover, share, and rate delicious recipes from home cooks everywhere.</p>
</div>

<div class="row row-cols-1 row-cols-md-2 g-4 mb-4">
    @foreach (var category in categories)
    {
        <div class="col">
            <a href="category/@Uri.EscapeDataString(category.Name)" class="text-decoration-none">
                <div class="card h-100 shadow-sm category-card">
                    <div class="card-body text-center">
                        <div class="display-3 mb-2">@category.Emoji</div>
                        <h3 class="card-title">@category.Name</h3>
                        <p class="card-text text-muted">@category.Description</p>
                        <span class="badge bg-primary rounded-pill">@category.RecipeCount recipes</span>
                    </div>
                </div>
            </a>
        </div>
    }
</div>

<div class="text-center">
    <a href="submit" class="btn btn-success btn-lg">📝 Submit Your Recipe</a>
</div>

@code {
    [Inject] public RecipeService RecipeService { get; set; } = default!;
    private List<RecipeCommunity.Models.CategoryInfo> categories = [];

    protected override void OnInitialized()
    {
        categories = RecipeService.GetCategories();
    }
}

@page "/category/{CategoryName}"
@using RecipeCommunity.Services
@using RecipeCommunity.Models

<PageTitle>@CategoryName Recipes</PageTitle>

<nav aria-label="breadcrumb">
    <ol class="breadcrumb">
        <li class="breadcrumb-item"><a href="/">Home</a></li>
        <li class="breadcrumb-item active">@CategoryName</li>
    </ol>
</nav>

<h2>@CategoryName</h2>

@if (recipes.Count == 0)
{
    <div class="alert alert-info">No recipes found in this category.</div>
}
else
{
    <div class="row row-cols-1 row-cols-md-2 row-cols-lg-3 g-4">
        @foreach (var recipe in recipes)
        {
            <div class="col">
                <a href="recipe/@recipe.Id" class="text-decoration-none">
                    <div class="card h-100 shadow-sm category-card">
                        <div class="card-body">
                            <div class="display-4 text-center mb-2">@recipe.ImageEmoji</div>
                            <h5 class="card-title">@recipe.Title</h5>
                            <p class="card-text text-muted">@recipe.Description</p>
                            <div class="d-flex justify-content-between align-items-center">
                                <small class="text-warning">
                                    @for (int i = 1; i <= 5; i++)
                                    {
                                        <span>@(i <= (int)Math.Round(recipe.AverageRating) ? "★" : "☆")</span>
                                    }
                                </small>
                                <small class="text-muted">@recipe.TotalRatings ratings</small>
                            </div>
                        </div>
                    </div>
                </a>
            </div>
        }
    </div>
}

@code {
    [Parameter] public string CategoryName { get; set; } = string.Empty;
    [Inject] public RecipeService RecipeService { get; set; } = default!;
    private List<Recipe> recipes = [];

    protected override void OnParametersSet()
    {
        recipes = RecipeService.GetRecipesByCategory(Uri.UnescapeDataString(CategoryName));
    }
}

@page "/recipe/{Id:int}"
@using RecipeCommunity.Services
@using RecipeCommunity.Models

<PageTitle>@(recipe?.Title ?? "Recipe")</PageTitle>

@if (recipe is null)
{
    <div class="alert alert-warning">Recipe not found.</div>
}
else
{
