@using RecipeCommunity.Services

<div class="star-rating my-2">
    @for (int i = 1; i <= 5; i++)
    {
        var star = i;
        <span class="star @(star <= (hasRated ? selectedRating : hoverRating) ? "filled" : "")"
              @onclick="() => Rate(star)"
              @onmouseover="() => hoverRating = star"
              @onmouseout="() => hoverRating = 0"
              role="button"
              title="@star star@(star > 1 ? "s" : "")">
            @(star <= (hasRated ? selectedRating : (hoverRating > 0 ? hoverRating : 0)) ? "★" : "☆")
        </span>
    }
</div>

@if (hasRated)
{
    <small class="text-success">Thanks! You rated this @selectedRating star@(selectedRating > 1 ? "s" : "").</small>
}
else
{
    <small class="text-muted">Click a star to rate</small>
}

@code {
    [Parameter] public int RecipeId { get; set; }
    [Inject] public RecipeService RecipeService { get; set; } = default!;

    private int hoverRating;
    private int selectedRating;
    private bool hasRated;

    private void Rate(int stars)
    {
        if (hasRated) return;
        selectedRating = stars;
        hasRated = true;
        RecipeService.AddRating(RecipeId, stars);
    }
}

